if($('#ss-phase-direction'))$('#ss-phase-direction').oninput=e=>{const g=M.stageGroups(p).find(g=>g.id===p.selectedPhase)||M.stageGroups(p)[0];p.outlinePhases??=[];let phase=p.outlinePhases.find(x=>x.id===g.id);if(!phase){phase={id:g.id,title:g.title};p.outlinePhases.push(phase);}phase.direction=e.target.value;M.touch(p,'outline');save();};
