if($('#ss-trait-input')){const el=$('#ss-trait-input');el.oninput=()=>traitDraft=el.value;el.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.isComposing){e.preventDefault();const t=el.value.trim();if(!t)return;const c=activeCharacter();c.personalityTags??=[];if(!c.personalityTags.includes(t))c.personalityTags.push(t);traitDraft='';if(!characterDraft){M.touch(p,'analysis');p.analysisConfirmed=false;save();}render();$('#ss-trait-input')?.focus();}};}

if($('#ss-work-request'))$('#ss-work-request').oninput=e=>{p.workAssistant??={};const a=p.workAssistant[workTab()]??={messages:[],draft:''};a.draft=e.target.value;save();};
