host.querySelectorAll('[data-pref-search]').forEach(el=>{el.onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();const key=el.dataset.prefSearch,label=el.value.trim();if(!label)return;const preset=presets[key].find(x=>x[1]===label);M.preferenceToggle(p,prefStore(true),key,preset?.[0]||M.id('custom'),label);prefUI[key]='';save();const scroll=$('.ss-idea-chat')?.scrollTop;render();$('.ss-idea-chat').scrollTop=scroll;}};el.oninput=()=>{prefUI[el.dataset.prefSearch]=el.value;host.querySelectorAll('[data-pref-options="'+el.dataset.prefSearch+'"] [data-pref-option]').forEach(x=>x.hidden=!x.dataset.prefOption.includes(el.value));};});
host.querySelectorAll('[data-pref-legacy]').forEach(el=>el.oninput=()=>{const key=el.dataset.prefLegacy,v=M.preferenceState(p,prefStore(),key);v.legacy=el.value;v.value=[v.legacy,...v.tags.map(t=>t.label)].filter(Boolean).join('、');p.settings[key]=v.value;prefStore(true)[key]=v;save();});
