host.querySelectorAll('[data-plan]').forEach(el=>el.oninput=()=>{const d=M.ideaDesk(p);d.plans[d.selected][el.dataset.plan]=el.value;if(el.dataset.plan==='title'){p.title=el.value;$('#ss-projects').selectedOptions[0].textContent=p.title;}save();});
